// Name dataset (public/names.json, generated by scripts/build-names.mjs) and filters.
import { t, type Key } from './i18n';

export interface RawName {
  /** Displayed spelling */
  n: string;
  /** Key (letters only, no accents) */
  k: string;
  /** Share of girls, 0-100 */
  f: number;
  /** Frequency per country: "fr9es7..." (code + hex level 1-d, 10 ≈ 2% of births of one sex) */
  c: string;
  /** Other spellings */
  a?: string[];
  /** France: births per decade 1950-2020 (8 values), last 10 years, last year */
  fr?: number[];
  /** Spain: number of people with this name */
  es?: number;
  /** Quebec: births since 2016 */
  qc?: number;
}

export interface Name extends RawName {
  idx: number;
  /** Level per country */
  freq: Record<string, number>;
  gender: Gender;
  /** Number of letters */
  len: number;
  compound: boolean;
}

export type Gender = 'f' | 'm' | 'u';

export interface Country {
  code: string;
  region: string;
}

export interface Dataset {
  version: string;
  hash: number;
  countries: Country[];
  /** Region codes, in display order */
  regions: string[];
  names: Name[];
  byKey: Map<string, Name>;
}

export async function loadDataset(): Promise<Dataset> {
  const res = await fetch(`${import.meta.env.BASE_URL}names.json`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const raw = await res.json();
  const names: Name[] = (raw.names as RawName[]).map((r, idx) => {
    const freq: Record<string, number> = {};
    for (const m of r.c.matchAll(/([a-z]{2})([0-9a-d])/g)) freq[m[1]] = parseInt(m[2], 16);
    return {
      ...r,
      idx,
      freq,
      gender: r.f >= 85 ? 'f' : r.f <= 15 ? 'm' : 'u',
      len: r.k.length,
      compound: /[- ]/.test(r.n),
    };
  });
  return { ...raw, names, byKey: new Map(names.map((n) => [n.k, n])) };
}

// ---------------------------------------------------------------------------------------------

export const genderLabel = (g: Gender) => t(`gender.${g}`);

export const LEVELS: { min: number; label: Key }[] = [
  { min: 1, label: 'level.all' },
  { min: 3, label: 'level.known' },
  { min: 6, label: 'level.common' },
  { min: 9, label: 'level.veryCommon' },
];

/** Label of a frequency level */
export function levelLabel(level: number): string {
  if (level >= 10) return t('freq.veryPopular');
  if (level >= 8) return t('freq.popular');
  if (level >= 6) return t('freq.common');
  if (level >= 3) return t('freq.uncommon');
  return t('freq.rare');
}

export const countryLabel = (code: string) => t(`country.${code}` as Key);
export const regionLabel = (code: string) => t(`region.${code}` as Key);

export interface Filters {
  genders: Gender[];
  /** Country codes or "region:xxx" */
  origins: string[];
  /** any = at least one origin; all = every origin ("compatible" names) */
  originMode: 'any' | 'all';
  /** Minimum level in the selected origins */
  minLevel: number;
  /** Exclude very popular names (level ≥ 10) in the selected origins */
  notTooPopular: boolean;
  minLen: number;
  maxLen: number;
  startsWith: string;
  excludeCompound: boolean;
}

export const DEFAULT_FILTERS: Filters = {
  genders: ['f', 'm', 'u'],
  origins: [],
  originMode: 'any',
  minLevel: 1,
  notTooPopular: false,
  minLen: 2,
  maxLen: 20,
  startsWith: '',
  excludeCompound: true,
};

/** Level of a name for an origin (country, or region = max over its countries) */
export function originLevel(ds: Dataset, name: Name, origin: string): number {
  if (origin.startsWith('region:')) {
    const region = origin.slice(7);
    let max = 0;
    for (const c of ds.countries) if (c.region === region) max = Math.max(max, name.freq[c.code] ?? 0);
    return max;
  }
  return name.freq[origin] ?? 0;
}

export function originLabel(origin: string): string {
  return origin.startsWith('region:') ? regionLabel(origin.slice(7)) : countryLabel(origin);
}

const fold = (s: string) => s.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();

export function makeFilter(ds: Dataset, f: Filters): (n: Name) => boolean {
  const prefix = fold(f.startsWith.trim()).replace(/[^a-z]/g, '');
  const genders = new Set(f.genders);
  return (n) => {
    if (!genders.has(n.gender)) return false;
    if (n.len < f.minLen || n.len > f.maxLen) return false;
    if (f.excludeCompound && n.compound) return false;
    if (prefix && !n.k.startsWith(prefix)) return false;
    if (f.origins.length) {
      const levels = f.origins.map((o) => originLevel(ds, n, o));
      const ok = (l: number) => l >= f.minLevel;
      if (f.originMode === 'all' ? !levels.every(ok) : !levels.some(ok)) return false;
      if (f.notTooPopular && levels.some((l) => l >= 10)) return false;
    } else {
      const max = Math.max(0, ...Object.values(n.freq));
      if (max < f.minLevel) return false;
      if (f.notTooPopular && max >= 10) return false;
    }
    return true;
  };
}

/** Accent-insensitive search on the name and its spellings */
export function matchesSearch(n: Name, q: string): boolean {
  const s = fold(q.trim());
  if (!s) return true;
  return fold(n.n).includes(s) || (n.a ?? []).some((a) => fold(a).includes(s));
}

/** Main countries of a name, by decreasing level; countries in `prefer` (filtered origins) first */
export function topCountries(ds: Dataset, n: Name, max = 6, prefer: string[] = []): { country: Country; level: number }[] {
  const preferred = new Set<string>();
  for (const o of prefer) {
    if (o.startsWith('region:')) ds.countries.filter((c) => c.region === o.slice(7)).forEach((c) => preferred.add(c.code));
    else preferred.add(o);
  }
  const rank = (code: string) => (preferred.has(code) ? 1 : 0);
  return Object.entries(n.freq)
    .sort((a, b) => rank(b[0]) - rank(a[0]) || b[1] - a[1])
    .slice(0, max)
    .map(([code, level]) => ({ country: ds.countries.find((c) => c.code === code)!, level }))
    .filter((x) => x.country);
}

/** Overall popularity: weighted sum of levels (for sorting) */
export function popularity(n: Name): number {
  let s = 0;
  for (const l of Object.values(n.freq)) s += 2 ** l;
  return s;
}

export function shuffle<T>(arr: T[]): T[] {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
